+static void counting_sort_pass(uint32_t* input, uint32_t* output, size_t n, int pass) {
+    // 8-bit pass, 256 buckets
+    constexpr int BUCKET_BITS = 8;
+    constexpr int RADIX = 1 << BUCKET_BITS;
+    const uint32_t MASK = RADIX - 1;
+    int SHIFT = pass * BUCKET_BITS;
+
+    // Count frequencies
+    int counts[RADIX] = {0};
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t bucket_idx = (input[i] >> SHIFT) & MASK;
+        counts[bucket_idx]++;
+    }
+
+    // Compute cumulative sums (start indices)
+    int sum = 0;
+    for (int i = 0; i < RADIX; ++i) {
+        int temp = counts[i];
+        counts[i] = sum;
+        sum += temp;
+    }
+
+    // Place elements in output buffer stably
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t bucket_idx = (input[i] >> SHIFT) & MASK;
+        output[counts[bucket_idx]++] = input[i];
+    }
 }

 extern "C" void sort_u32(uint32_t* a, size_t n) {
